def stable_merge(left, right):
    out = []
    i = j = 0
    while i < len(left) and j < len(right):
        # <= ensures left (earlier) element wins on equal priority
        if left[i][0] <= right[j][0]:
            out.append(left[i])
            i += 1
        else:
            out.append(right[j])
            j += 1
    out.extend(left[i:])
    out.extend(right[j:])
    return out

def stable_merge_sort(items):
    if len(items) <= 1:
        return items
    mid = len(items) // 2
    return stable_merge(stable_merge_sort(items[:mid]), stable_merge_sort(items[mid:]))

