from functools import cmp_to_key

def compare_concat(a, b):
    if a + b > b + a:
        return -1
    if a + b < b + a:
        return 1
    return 0

tokens = input().split()
tokens.sort(key=cmp_to_key(compare_concat))
if tokens[0] == "0":
    print("0")
else:
    print("".join(tokens))

